// Generated by Cypress Author on 2026-11-25.
// Regrouper les vérifications de l'inventaire à partir de la fixture produits.
describe('Swag Labs inventory fixture validation', () => {
    // Se connecter avant le test avec la commande partagée.
    beforeEach(() => {
        // Ouvrir une session utilisateur standard sur l'inventaire.
        cy.login();
    });

    // Fermer la session après le test avec la commande partagée.
    afterEach(() => {
        // Déconnecter l'utilisateur après les vérifications.
        cy.logout();
    });

    // Définir le scénario de comparaison du catalogue et de la fixture.
    it('affiche les six produits avec les noms, descriptions et prix attendus', () => {
        // Charger les données officielles de produits depuis la fixture JSON.
        cy.fixture('swaglabs_products').then((products) => {
            // Vérifier qu'exactement six produits sont affichés puis comparer chaque ligne par index.
            cy.get('.inventory_item').should('have.length', 6).each(($item, index) => {
                // Vérifier que le nom du produit correspond à la fixture au même index.
                cy.wrap($item).find('.inventory_item_name').should('be.visible').and('have.text', products[index].name);
                // Vérifier que la description du produit correspond à la fixture au même index.
                cy.wrap($item).find('.inventory_item_desc').should('be.visible').and('have.text', products[index].description);
                // Vérifier que le prix du produit correspond à la fixture au même index.
                cy.wrap($item).find('.inventory_item_price').should('be.visible').and('have.text', products[index].price);
            });
        });
    });
});
